import {marks,directions} from './cartographer-content.mjs';
export const repeatPages=['map','block','trace','kept'];
const rows=[['sign-out','A sign for the market',3,'post','cafe','Carry a sign from Post Office to Café.'],['flowers-out','Flowers for the café',4,'post','cafe','Carry flowers from Post Office to Café.'],['sign-back','Return the sign',3,'cafe','post','Return the sign from Café to Post Office.'],['basket-back','Return the flower basket',4,'cafe','post','Return the flower basket from Café to Post Office.']];
const symbols={n:'↑',e:'→',s:'↓',w:'←'};
export const repeatCases=rows.map(([id,title,k,from,to,request])=>({version:1,id,title,story:'The town’s market courier is trying a compact flight plan. The bracket holds two arrows, and the whole ordered pair repeats. This is an original fictional model map, not real navigation.',request,gridMin:0,gridMax:5,stepDistance:1,distanceUnit:'model metres',drawingVersion:1,marks:structuredClone(marks),directions:directions.map(d=>({...d,symbol:symbols[d.id]})),places:{post:{x:1,y:1},bridge:{x:k,y:1},cafe:{x:k,y:k},garden:{x:1,y:k}},from,to,pictureText:`An invented intersection grid from zero to five on both axes: x goes across, y goes up. Post Office is at (1, 1), Bridge at (${k}, 1), Café at (${k}, ${k}) and Garden at (1, ${k}). One interval is one model metre. This is a direct delivery without an intermediate stop.`,help:'Both arrows belong inside the repeat bracket. Repeat 3 [East, North] means East, North, East, North, East, North. It does not mean East, East, East, North, North, North, or repeating only the last arrow. For outward jobs, [East, North] and [North, East] can be fitting staircases; return jobs can use [West, South] and [South, West]. Each pair of fitting orders makes different paths. Count the two block slots, the repetitions, proposed moves and actual travelled moves separately. A blocked attempt does not travel outside the grid; keep the whole proposed plan and inspect its travelled prefix. Separate example: on another map, start (0,0) and Repeat 2 [East,East]. The four steps visit (1,0), (2,0), (3,0), (4,0). This example changes none of your current work. The computer follows these exact supplied rules, not what it guesses you intended. Labels, expanded arrows and feedback supply teaching; running this finite model does not establish independent prediction, multiplication, writing or general programming.'}));
export const repeatSource=id=>{const s=repeatCases.find(s=>s.id===id);return s?structuredClone(s):null;};
